import json
p='f561a6af-86ca-4696-8d72-bdc29ab6e788.jsonl'
rows=[]
with open(p) as f:
    for line in f:
        line=line.strip()
        if not line: continue
        try: d=json.loads(line)
        except: continue
        rows.append(d)
def text_of(m):
    c=m.get('content')
    if isinstance(c,str): return c
    out=[]
    for b in (c or []):
        if not isinstance(b,dict): continue
        t=b.get('type')
        if t=='text': out.append(b.get('text',''))
        elif t=='tool_use':
            out.append(f"[TOOL_USE {b.get('name')}] "+json.dumps(b.get('input',{}),ensure_ascii=False)[:2000])
        elif t=='tool_result':
            cc=b.get('content')
            s=cc if isinstance(cc,str) else json.dumps(cc,ensure_ascii=False)
            out.append(f"[TOOL_RESULT] {s[:1500]}")
    return '\n'.join(out)
for i in range(976, len(rows)):
    r=rows[i]
    print('='*20, i, r.get('type'), r.get('timestamp'))
    if r.get('type') in ('assistant','user'):
        print(text_of(r.get('message',{}))[:2500])
    else:
        print(json.dumps(r, ensure_ascii=False)[:500])
EOF

