1	/**
2	 * @file line_chart_widget.cpp
3	 * @brief LineChartWidget 实现
4	 */
5	
6	#include "line_chart_widget.hpp"
7	
8	#include <QFontMetrics>
9	#include <QPainter>
10	#include <QPaintEvent>
11	#include <QPainterPath>
12	#include <QPen>
13	
14	#include <algorithm>
15	#include <limits>
16	
17	namespace weaknet {
18	namespace dashboard {
19	
20	namespace {
21	
22	/// 绘图区相对控件边缘的留白（为坐标轴标签留空间）
23	constexpr int kMarginLeft = 44;
24	constexpr int kMarginRight = 12;
25	constexpr int kMarginTop = 28;
26	constexpr int kMarginBottom = 24;
27	
28	/// 网格线数量
29	constexpr int kGridLines = 4;
30	
31	} // namespace
32	
33	LineChartWidget::LineChartWidget(QWidget* parent) : QWidget(parent) {
34	    // 让控件至少在布局里有合理的最小尺寸
35	    setMinimumSize(240, 140);
36	}
37	
38	void LineChartWidget::setSeries(const HistorySeries& series) {
39	    scores_.clear();
40	    labels_.clear();
41	    scores_.reserve(static_cast<int>(series.points.size()));
42	    for (const HistoryPoint& p : series.points) {
43	        scores_.push_back(p.score);
44	        labels_.push_back(QString::fromStdString(p.ts));
45	    }
46	    update();
47	}
48	
49	void LineChartWidget::clear() {
50	    scores_.clear();
51	    labels_.clear();
52	    update();
53	}
54	
55	void LineChartWidget::setLineColor(const QColor& color) {
56	    line_color_ = color;
57	    update();
58	}
59	
60	void LineChartWidget::setTitle(const QString& title) {
61	    title_ = title;
62	    update();
63	}
64	
65	void LineChartWidget::setAutoScale(bool auto_scale) {
66	    auto_scale_ = auto_scale;
67	    update();
68	}
69	
70	void LineChartWidget::paintEvent(QPaintEvent* event) {
71	    Q_UNUSED(event);
72	    QPainter painter(this);
73	    painter.setRenderHint(QPainter::Antialiasing, true);
74	    paint(&painter, rect());
75	}
76	
77	void LineChartWidget::paint(QPainter* painter, const QRect& area) const {
78	    if (!painter || area.width() <= 0 || area.height() <= 0) {
79	        return;
80	    }
81	
82	    painter->save();
83	
84	    // --- 标题 ---
85	    if (!title_.isEmpty()) {
86	        QFont f = painter->font();
87	        f.setBold(true);
88	        painter->setFont(f);
89	        painter->setPen(QColor(0x33, 0x33, 0x33));
90	        painter->drawText(QRect(area.left() + kMarginLeft, area.top() + 4,
91	                                area.width() - kMarginLeft - kMarginRight, kMarginTop - 6),
92	                          Qt::AlignLeft | Qt::AlignVCenter, title_);
93	        f.setBold(false);
94	        painter->setFont(f);
95	    }
96	
97	    // --- 绘图区 ---
98	    QRect plot(area.left() + kMarginLeft,
99	               area.top() + kMarginTop,
100	               area.width() - kMarginLeft - kMarginRight,
101	               area.height() - kMarginTop - kMarginBottom);
102	
103	    if (plot.width() <= 1 || plot.height() <= 1) {
104	        painter->restore();
105	        return;
106	    }
107	
108	    // --- Y 轴范围 ---
109	    double lo = 0.0;
110	    double hi = 100.0;
111	    if (auto_scale_ && !scores_.isEmpty()) {
112	        lo = *std::min_element(scores_.constBegin(), scores_.constEnd());
113	        hi = *std::max_element(scores_.constBegin(), scores_.constEnd());
114	        // 上下各留 10% 边距；全等值时给一个最小跨度避免除零
115	        const double span = hi - lo;
116	        if (span < 1e-6) {
117	            lo -= 5.0;
118	            hi += 5.0;
119	        } else {
120	            const double pad = span * 0.1;
121	            lo -= pad;
122	            hi += pad;
123	        }
124	    }
125	
126	    // --- 网格 + Y 轴刻度 ---
127	    painter->setPen(QPen(QColor(0xE0, 0xE0, 0xE0), 1, Qt::SolidLine));
128	    QFont small = painter->font();
129	    small.setPointSizeF(std::max(7.0, small.pointSizeF() - 1.0));
130	    painter->setFont(small);
131	
132	    for (int i = 0; i <= kGridLines; ++i) {
133	        const double ratio = static_cast<double>(i) / kGridLines;
134	        const int y = plot.bottom() - static_cast<int>(ratio * plot.height());
135	
136	        painter->setPen(QPen(QColor(0xE0, 0xE0, 0xE0), 1, Qt::SolidLine));
137	        painter->drawLine(plot.left(), y, plot.right(), y);
138	
