/**
 * @file line_chart_widget.hpp
 * @brief QPainter 自绘折线图
 *
 * ## 为什么不用 Qt Charts
 *
 * 1. 板端**没装** `libqt5charts5`（实测 `dpkg -l | grep -i chart` 为空）
 * 2. `QChart` 在 Mesa 软件渲染下帧率差
 * 3. 自绘可以 `render()` 到 `QImage` 做像素级断言，**不需要显示器**
 *
 * 第 3 点是关键：开发板目前没接 HDMI 显示器，如果图表只能在屏幕上验证，
 * 这条路在硬件到手前就是死的。渲染到 QImage 让 UI 层也能在 x86 上单测。
 *
 * ## 绘制与控件分离
 *
 * `paint(QPainter*, QRect)` 是纯绘制函数，接收 QPainter 和矩形区域，
 * 不读 `this->width()`。`paintEvent()` 只是把 `rect()` 转给它。
 *
 * 这样测试可以：
 *
 * ```cpp
 * QImage img(400, 200, QImage::Format_RGB32);
 * img.fill(Qt::white);
 * QPainter p(&img);
 * chart.paint(&p, img.rect());
 * p.end();
 * // 断言 img 里出现了曲线颜色的像素
 * ```
 */

#ifndef WEAKNET_QT_DASHBOARD_LINE_CHART_WIDGET_HPP
#define WEAKNET_QT_DASHBOARD_LINE_CHART_WIDGET_HPP

#include <QColor>
#include <QString>
#include <QVector>
#include <QWidget>

#include "data/dashboard_data.hpp"

class QPainter;

namespace weaknet {
namespace dashboard {

/**
 * @brief 折线图控件
 *
 * 显示 `HistorySeries` 的分数随时间变化。
 *
 * 不持有数据的所有权，`setSeries()` 拷贝一份 QVector。
 */
class LineChartWidget : public QWidget {
    Q_OBJECT

public:
    explicit LineChartWidget(QWidget* parent = nullptr);

    /**
     * @brief 设置要绘制的数据
     *
     * 传入前应保证点已按时间正序排列（`parse_history()` 已做翻转）。
     */
    void setSeries(const HistorySeries& series);

    /// 清空数据
    void clear();

    /// 数据点数量
    int pointCount() const { return scores_.size(); }

    // --- 外观配置 ---

    void setLineColor(const QColor& color);
    void setTitle(const QString& title);

    /**
     * @brief Y 轴是否自动适配数据范围
     *
     * true（默认）：按数据 min/max 留边距
     * false：固定 [0, 100]
     */
    void setAutoScale(bool auto_scale);

    /**
     * @brief 纯绘制函数
     *
     * 不依赖控件几何，可直接对任意 QPainter 调用。
     */
    void paint(QPainter* painter, const QRect& area) const;

protected:
    void paintEvent(QPaintEvent* event) override;

private:
    QVector<double> scores_;
    QVector<QString> labels_;
    QColor line_color_{0x2E, 0x7D, 0x32};
    QString title_;
    bool auto_scale_{true};
};

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_LINE_CHART_WIDGET_HPP

/**
 * @file json_reader.hpp
 * @brief 轻量 JSON 读取器 —— 仅够看板使用，不追求通用性
 *
 * ## 为什么不引第三方库
 *
 * 项目全仓不使用 nlohmann/json。`server/src/net_info.cpp:15` 明确记录了
 * 这个决定：「使用自定义轻量 JSON 解析器（不依赖第三方库如 nlohmann/json）」。
 * 看板沿用同样策略，避免在嵌入式目标上引入额外依赖。
 *
 * ## 与 net_info.cpp 的关系
 *
 * `net_info.cpp` 里的 JSON 工具函数是文件内 static 的，不对外暴露。
 * 本文件独立实现一份，只提供看板需要的能力：
 *   - 按 key 取字符串 / 数字 / 布尔
 *   - 按 key 取数组（字符串数组、对象数组）
 *   - 嵌套对象下钻
 *
 * 不做的事：序列化、写 JSON、未知类型推断、错误恢复。
 * 解析失败一律返回默认值，由调用方通过 `ok()` 判断整体有效性。
 *
 * ## 设计取舍
 *
 * 使用「路径式查找」而非完整 DOM 树：
 *
 * ```cpp
 * JsonReader r(json);
 * auto state = r.getString("overall.state");
 * auto score = r.getDouble("overall.display_score", -1.0);
 * ```
 *
 * 理由：看板只需要读少数已知字段，构建完整 DOM 是浪费。
 * 代价：同一个路径重复查找会重复扫描。看板场景下 JSON 只有几 KB，
 * 这点开销可忽略。
 */

#ifndef WEAKNET_QT_DASHBOARD_JSON_READER_HPP
#define WEAKNET_QT_DASHBOARD_JSON_READER_HPP

#include <string>
#include <vector>

namespace weaknet {
namespace dashboard {

/**
 * @brief 轻量 JSON 读取器
 *
 * 构造时不做完整解析（懒解析），首次调用 getXxx 时才扫描。
 * 这样如果调用方只关心一个字段，就不必为整棵 JSON 付出代价。
 */
class JsonReader {
public:
    explicit JsonReader(const std::string& json);

    /**
     * @brief 整个 JSON 是否看起来有效（非空、首尾括号匹配）
     *
     * 这不是严格的语法校验，只是快速排除「空串 / 错误信息 / 截断」。
     */
    bool valid() const;

    /**
     * @brief 按路径取字符串
     *
     * @param path     点分路径，如 "overall.state"；顶层字段直接写 "schema_version"
     * @param fallback 找不到或类型不符时的返回值
     */
    std::string getString(const std::string& path, const std::string& fallback = "") const;

    /**
     * @brief 按路径取数字
     */
    double getDouble(const std::string& path, double fallback = 0.0) const;

    /**
     * @brief 按路径取整数
     */
    int getInt(const std::string& path, int fallback = 0) const;

    /**
     * @brief 按路径取布尔
     */
    bool getBool(const std::string& path, bool fallback = false) const;

    /**
     * @brief 按路径取字符串数组
     *
     * 用于 `warnings: ["a","b"]` 这类结构。
     */
    std::vector<std::string> getStringArray(const std::string& path) const;

    /**
     * @brief 按路径取对象数组的原始 JSON 片段
     *
     * 用于 `evidence: [{"metric":...,"value":...}]` 这类结构。
     * 返回每个元素的原始 JSON 字符串，调用方再用 JsonReader 逐个解析。
     *
     * 之所以不直接返回结构体：数组元素形状由调用方决定，
     * 在这里做通用映射反而增加耦合。
     */
    std::vector<std::string> getObjectArray(const std::string& path) const;

    /**
     * @brief 判断某个路径是否存在且非 null
     */
    bool has(const std::string& path) const;

    /**
     * @brief 判断根节点是不是数组
     *
     * `GetHistory` 返回的是顶层数组，`locate()` 只处理对象根节点，
     * 因此需要这个额外入口。
     */
    bool rootIsArray() const;

    /**
     * @brief 取根数组的每个元素原始 JSON
     *
     * 仅在 `rootIsArray()` 为真时有意义。
     */
    std::vector<std::string> getRootObjectArray() const;

    /**
     * @brief 取根数组的长度
     */
    size_t rootArraySize() const;

    /**
     * @brief 取原始 JSON 字符串（用于调试）
     */
    const std::string& raw() const { return json_; }

private:
    /**
     * @brief 定位路径对应的值起始位置
     *
     * @return 值的起始下标；找不到返回 std::string::npos
     */
    size_t locate(const std::string& path) const;

    /**
     * @brief 从 pos 开始跳过一个值，返回其结束位置（不含）
     */
    size_t skipValue(size_t pos) const;

    /**
     * @brief 从 pos 开始跳过一个字符串，返回结束引号之后的位置
     */
    size_t skipString(size_t pos) const;

    /**
     * @brief 从 pos 开始跳过一个对象或数组
     */
    size_t skipContainer(size_t pos) const;

    /**
     * @brief 跳过空白
     */
    size_t skipWhitespace(size_t pos) const;

    /**
     * @brief 解析 pos 处的字符串值（含转义）
     */
    std::string parseStringAt(size_t pos, size_t* end_out) const;

    /**
     * @brief 在 [begin, end) 范围内按顶层逗号切分
     */
    std::vector<std::pair<size_t, size_t>> splitTopLevel(size_t begin, size_t end) const;

    std::string json_;
};

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_JSON_READER_HPP

/**
 * @file dashboard_data.hpp
 * @brief Qt 看板使用的 POD 数据结构
 *
 * ## 数据来源
 *
 * 全部来自现有 D-Bus 只读方法，经 `client/weaknet_client.h` 的 C API 获取：
 *
 *   weaknet_get_network_experience()  → ExperienceSnapshot
 *   weaknet_get_diagnosis()           → DiagnosisSnapshot
 *   weaknet_get_history()             → vector<HistoryPoint>
 *
 * 不新增 D-Bus 方法，不修改服务端。
 *
 * ## 为什么单独定义 POD
 *
 * 参考 `monitor_system` 的 `monitor_data.h` 做法：**把传输层挡在 UI 之外**。
 *
 * 直接让 UI 解析 JSON 的后果：
 *   - JSON 字段改名 → 改 UI 代码
 *   - UI 代码里出现大量 `getString("overall.state")` 这类魔法字符串
 *   - 无法对数据映射逻辑做单元测试
 *
 * 分离后：
 *   - JSON → POD 是纯函数，可独立单测
 *   - UI 只读 POD，不知道 JSON 长什么样
 *
 * ## 字段与 schema v2 的对应
 *
 * schema v2 的实际形状由 `server/include/assurance/legacy_adapter.hpp:162`
 * 的 `toExperienceJsonV2()` 定义。本文件的字段与之逐项对应。
 */

#ifndef WEAKNET_QT_DASHBOARD_DASHBOARD_DATA_HPP
#define WEAKNET_QT_DASHBOARD_DASHBOARD_DATA_HPP

#include <cstdint>
#include <string>
#include <vector>

namespace weaknet {
namespace dashboard {

/**
 * @brief 单个维度的 SLE 评估结果
 *
 * 对应 JSON: `network_health.ip_reachability` 等
 */
struct SleItem {
    /// 维度标识（如 "ip_reachability"、"dns"）
    std::string key;

    /// 状态：GOOD / DEGRADED / BAD / UNKNOWN
    ///
    /// 取值来自 `server/include/assurance/health_state.hpp:15-23`
    /// 的 `healthStateToString()`。注意不是 HEALTHY/FAILED。
    std::string state;

    /// 覆盖率：FULL_FOR_PROFILE / PARTIAL / NONE
    ///
    /// 取值来自同文件 `coverageToString()`（`:31-38`）。注意不是 FULL。
    std::string coverage;

    /// 适用性：APPLICABLE / NOT_APPLICABLE
    std::string applicability;

    /// 原因说明（机器可读 token）
    std::string reason;

    /// 是否携带有效评估（state != UNKNOWN 且 coverage != NONE）
    bool has_value() const {
        return state != "UNKNOWN" && !state.empty();
    }

    /// 该维度是否适用于当前链路形态（如 RF Health 在有线链路下不适用）
    bool applicable() const { return applicability != "NOT_APPLICABLE"; }
};

/**
 * @brief 单条证据
 *
 * 对应 JSON: `network_health.ip_reachability.evidence[]`
 */
struct EvidenceItem {
    std::string metric;
    double value = 0.0;
    std::string detail;
};

/**
 * @brief 网络体验快照（schema v2）
 *
 * 对应 `GetNetworkExperience` 的返回。
 *
 * **注意**：服务端在无快照或快照过期时返回的是
 * `{"schema_version":2,"state":"UNKNOWN","coverage":"NONE","reason":"..."}`，
 * 此时顶层没有 `overall` 对象。解析时需兼容这种形状。
 */
struct ExperienceSnapshot {
    int schema_version = 0;

    /// 被评估的网卡名（如 "wlan0"）
    std::string interface_name;

    /// 评估档位（如 "FULL" / "PARTIAL"）
    std::string assessment_profile;

    // --- overall ---
    std::string overall_state = "UNKNOWN";
    std::string overall_coverage = "NONE";
    double display_score = 0.0;

    // --- network_health（4 项）---
    SleItem ip_reachability;
    SleItem responsiveness;
    SleItem reliability;
    SleItem rf_health;

    // --- service_health（9 项）---
    SleItem dns_service;
    SleItem tcp_connect;
    SleItem tcp_rtt;
    SleItem http_access;
    SleItem captive_portal;
    SleItem active_dns;
    SleItem active_tcp;
    SleItem active_https;
    SleItem active_portal;

    /// 警告列表
    std::vector<std::string> warnings;

    /// 首要问题（无则为空）
    std::string primary_issue;

    /// 顶层失效原因（无快照 / 快照过期时非空）
    std::string unavailable_reason;

    /**
     * @brief 是否是可展示的有效快照
     *
     * 服务端返回 UNKNOWN 时（no_assessment_yet / stale_assessment），
     * 看板应显示「等待评估」而不是空白或 0 分。
     */
    bool available() const {
        return unavailable_reason.empty() && overall_state != "UNKNOWN";
    }

    /// 按状态汇总各维度计数：健康 / 降级 / 失败 / 未知
    void count_by_state(int* healthy, int* degraded, int* failed, int* unknown) const;
};

/**
 * @brief 被排除的候选原因
 *
 * 对应 JSON: `excluded_causes[].{cause,reason}`
 */
struct ExcludedCause {
    std::string cause;
    std::string reason;
};

/**
 * @brief 建议动作
 *
 * 对应 JSON: `actions[].{priority,action_id,params}`
 *
 * 只是**建议**。真正执行必须走 `weaknet_execute_action()`，
 * 且该 D-Bus 方法要求 root 权限（`dbus_service.cpp:requireRootCaller`）。
 * 看板不自行执行任何动作。
 */
struct ActionSuggestion {
    int priority = 1;
    std::string action_id;
};

/**
 * @brief 诊断结论快照
 *
 * 对应 `GetDiagnosis` 的返回（DiagnosisFacts JSON）。
 *
 * 字段逐项依据 `server/include/assurance/diagnosis_engine.hpp:44-85`
 * 的 `DiagnosisFacts::toJson()`：
 *
 * ```json
 * {"fault_domain":"...","primary_issue":"...","confidence":"HIGH|MEDIUM|LOW",
 *  "secondary_issues":["..."],"evidence_refs":["..."],
 *  "excluded_causes":[{"cause":"...","reason":"..."}],
 *  "actions":[{"priority":1,"action_id":"...","params":{...}}],
 *  "default_summary_template":"..."}
 * ```
 *
 * 注意 `confidence` 是**字符串枚举**，不是数值。
 */
struct DiagnosisSnapshot {
    /// 是否成功取得诊断
    bool valid = false;

    /// 故障域（如 "DNS" / "RF" / "TCP" / "HTTP" / "NONE"）
    std::string fault_domain;

    /// 首要问题描述（机器 token）
    std::string primary_issue;

    /// 置信度：HIGH / MEDIUM / LOW
    std::string confidence = "LOW";

    /// 次要问题
    std::vector<std::string> secondary_issues;

    /// 引用的证据 ID
    std::vector<std::string> evidence_refs;

    /// 被排除的候选原因
    std::vector<ExcludedCause> excluded_causes;

    /// 建议动作
    std::vector<ActionSuggestion> actions;

    /// 人读摘要模板
    std::string summary_template;

    /// 原始 JSON（保留，便于调试与后续扩展）
    std::string raw_json;
};

/**
 * @brief 历史趋势的单个数据点
 *
 * 对应 `GetHistory` 返回的数组元素。
 *
 * 字段名依据 `server/src/database_manager.cpp:703-740` 的 `queryHistory()`
 * 实际输出。注意 `ts` 是 **字符串** 而不是数字（SQLite 里按 TEXT 存），
 * 形如 "2026-11-05 14:23:10"。
 *
 * 该结构只保留看板画图需要的字段，其余（rssi/jitter/traffic 等）暂不映射，
 * 需要时再扩展。
 */
struct HistoryPoint {
    /// 采样时间（字符串，来自 `ts` 字段）
    std::string ts;

    /// 该时刻的综合分（来自 `score`，与 `overall_score` 同值）
    double score = 0.0;

    /// 该时刻的整体质量等级（来自 `overall_quality`）
    std::string overall_quality;

    /// 网卡名（来自 `iface`）
    std::string iface;

    /// 该行是否为 v2 之前的历史数据（来自 `legacy`）
    bool legacy = false;
};

/**
 * @brief 历史趋势序列
 */
struct HistorySeries {
    std::string interface_name;
    std::vector<HistoryPoint> points;

    bool empty() const { return points.empty(); }
};

// ---------------------------------------------------------------------------
// 解析函数（JSON 字符串 → POD）
// ---------------------------------------------------------------------------

/**
 * @brief 解析 schema v2 体验快照 JSON
 *
 * @param json `weaknet_get_network_experience()` 返回的字符串
 * @return 解析结果；输入无效时返回默认构造对象（available() 为 false）
 */
ExperienceSnapshot parse_experience(const std::string& json);

/**
 * @brief 解析诊断事实 JSON
 */
DiagnosisSnapshot parse_diagnosis(const std::string& json);

/**
 * @brief 解析历史趋势 JSON
 *
 * 服务端 `GetHistory` 实际返回的是顶层数组，见
 * `server/src/database_manager.cpp:686-744`。数据库不可用时返回
 * `{"error":"database not available"}`（对象而非数组），此时返回空序列。
 *
 * 各点按 `ORDER BY ts DESC` 逆序排列，这里统一翻转为时间正序，
 * 便于图表从左到右绘制。
 */
HistorySeries parse_history(const std::string& json);

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_DASHBOARD_DATA_HPP

