    while (cursor < end) {
        cursor = skipWhitespace(cursor);
        if (cursor >= end || json_[cursor] == ']') {
            break;
        }
        cursor = skipValue(cursor);
        ++count;
        cursor = skipWhitespace(cursor);
        if (cursor < end && json_[cursor] == ',') {
            ++cursor;
        }
    }
    return count;
}

