1	/**
2	 * @file dashboard_data.cpp
3	 * @brief POD 解析实现
4	 *
5	 * 每个 parse_xxx 都是纯函数：输入 JSON 字符串，输出 POD，不碰全局状态。
6	 * 这样可以在没有显示器、没有 D-Bus、没有服务端的情况下单元测试。
7	 */
8	
9	#include "dashboard_data.hpp"
10	#include "json_reader.hpp"
11	
12	#include <algorithm>
13	
14	namespace weaknet {
15	namespace dashboard {
16	
17	namespace {
18	
19	/**
20	 * @brief 从 JSON 的某个对象路径下解析一个 SLE 维度
21	 *
22	 * @param reader 已构造的 JsonReader
23	 * @param base   形如 "network_health.ip_reachability"
24	 * @param key    维度标识，写回 SleItem::key
25	 */
26	SleItem parse_sle(const JsonReader& reader, const std::string& base,
27	                  const std::string& key) {
28	    SleItem item;
29	    item.key = key;
30	    item.state = reader.getString(base + ".state", "UNKNOWN");
31	    item.coverage = reader.getString(base + ".coverage", "NONE");
32	    item.applicability = reader.getString(base + ".applicability", "NOT_APPLICABLE");
33	    item.reason = reader.getString(base + ".reason");
34	    return item;
35	}
36	
37	/**
38	 * @brief 判断 JSON 是否为数组（首个非空白字符是 '['）
39	 */
40	bool starts_with_array(const std::string& json) {
41	    for (char c : json) {
42	        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') continue;
43	        return c == '[';
44	    }
45	    return false;
46	}
47	
48	} // namespace
49	
50	// ---------------------------------------------------------------------------
51	// ExperienceSnapshot
52	// ---------------------------------------------------------------------------
53	
54	void ExperienceSnapshot::count_by_state(int* healthy, int* degraded,
55	                                        int* failed, int* unknown) const {
56	    int h = 0, d = 0, f = 0, u = 0;
57	    const SleItem* items[] = {
58	        &ip_reachability, &responsiveness, &reliability, &rf_health,
59	        &dns_service, &tcp_connect, &tcp_rtt, &http_access, &captive_portal,
60	        &active_dns, &active_tcp, &active_https, &active_portal,
61	    };
62	    // 状态字符串来自 healthStateToString()：GOOD / DEGRADED / BAD / UNKNOWN
63	    for (const SleItem* item : items) {
64	        if (!item->has_value()) {
65	            ++u;
66	        } else if (item->state == "GOOD") {
67	            ++h;
68	        } else if (item->state == "DEGRADED") {
69	            ++d;
70	        } else if (item->state == "BAD") {
71	            ++f;
72	        } else {
73	            ++u;
74	        }
75	    }
76	    if (healthy) *healthy = h;
77	    if (degraded) *degraded = d;
78	    if (failed) *failed = f;
79	    if (unknown) *unknown = u;
80	}
81	
82	ExperienceSnapshot parse_experience(const std::string& json) {
83	    ExperienceSnapshot snap;
84	    JsonReader reader(json);
85	    if (!reader.valid()) {
86	        snap.unavailable_reason = "invalid_json";
87	        return snap;
88	    }
89	
90	    snap.schema_version = reader.getInt("schema_version", 0);
91	
92	    // 先判断是否是「无快照 / 过期」的降级形状：
93	    // {"schema_version":2,"state":"UNKNOWN","coverage":"NONE","reason":"..."}
94	    // 这种形状顶层没有 overall 对象。
95	    const bool has_overall = reader.has("overall.state");
96	    if (!has_overall) {
97	        snap.overall_state = reader.getString("state", "UNKNOWN");
98	        snap.overall_coverage = reader.getString("coverage", "NONE");
99	        snap.unavailable_reason = reader.getString("reason", "unknown");
100	        return snap;
101	    }
102	
103	    snap.interface_name = reader.getString("interface");
104	    snap.assessment_profile = reader.getString("assessment_profile");
105	    snap.overall_state = reader.getString("overall.state", "UNKNOWN");
106	    snap.overall_coverage = reader.getString("overall.coverage", "NONE");
107	    snap.display_score = reader.getDouble("overall.display_score", 0.0);
108	
109	    snap.ip_reachability =
110	        parse_sle(reader, "network_health.ip_reachability", "ip_reachability");
