1	/**
2	 * @file line_chart_widget.cpp
3	 * @brief LineChartWidget 实现
4	 */
5	
6	#include "line_chart_widget.hpp"
7	
8	#include <QFontMetrics>
9	#include <QPainter>
10	#include <QPaintEvent>
11	#include <QPainterPath>
12	#include <QPen>
13	
14	#include <algorithm>
15	#include <limits>
16	
17	namespace weaknet {
18	namespace dashboard {
19	
20	namespace {
21	
22	/// 绘图区相对控件边缘的留白（为坐标轴标签留空间）
23	constexpr int kMarginLeft = 44;
24	constexpr int kMarginRight = 12;
25	constexpr int kMarginTop = 28;
26	constexpr int kMarginBottom = 24;
27	
28	/// 网格线数量
29	constexpr int kGridLines = 4;
30	
31	} // namespace
32	
33	LineChartWidget::LineChartWidget(QWidget* parent) : QWidget(parent) {
34	    // 让控件至少在布局里有合理的最小尺寸
35	    setMinimumSize(240, 140);
36	}
37	
38	void LineChartWidget::setSeries(const HistorySeries& series) {
39	    scores_.clear();
40	    labels_.clear();
41	    scores_.reserve(static_cast<int>(series.points.size()));
42	    for (const HistoryPoint& p : series.points) {
43	        scores_.push_back(p.score);
44	        labels_.push_back(QString::fromStdString(p.ts));
45	    }
46	    update();
47	}
48	
49	void LineChartWidget::setTitle(const QString& title) {
50	    title_ = title;
51	    update();
52	}
53	
54	void LineChartWidget::paintEvent(QPaintEvent* event) {
55	    Q_UNUSED(event);
56	    QPainter painter(this);
57	    painter.setRenderHint(QPainter::Antialiasing, true);
58	    paint(&painter, rect());
59	}
60	
61	void LineChartWidget::paint(QPainter* painter, const QRect& area) const {
62	    if (!painter || area.width() <= 0 || area.height() <= 0) {
63	        return;
64	    }
65	
66	    painter->save();
67	
68	    // --- 标题 ---
69	    if (!title_.isEmpty()) {
70	        QFont f = painter->font();
71	        f.setBold(true);
72	        painter->setFont(f);
73	        painter->setPen(QColor(0x33, 0x33, 0x33));
74	        painter->drawText(QRect(area.left() + kMarginLeft, area.top() + 4,
75	                                area.width() - kMarginLeft - kMarginRight, kMarginTop - 6),
76	                          Qt::AlignLeft | Qt::AlignVCenter, title_);
77	        f.setBold(false);
78	        painter->setFont(f);
79	    }
80	
81	    // --- 绘图区 ---
82	    QRect plot(area.left() + kMarginLeft,
83	               area.top() + kMarginTop,
84	               area.width() - kMarginLeft - kMarginRight,
85	               area.height() - kMarginTop - kMarginBottom);
86	
87	    if (plot.width() <= 1 || plot.height() <= 1) {
88	        painter->restore();
89	        return;
90	    }
91	
92	    // --- Y 轴范围 ---
93	    // 按数据 min/max 自适应，上下各留 10% 边距；全等值时给最小跨度避免除零。
94	    // 注意：小范围波动会被放大到撑满全高（如 20↔55 会铺满整个绘图区）。
95	    double lo = 0.0;
96	    double hi = 100.0;
97	    if (!scores_.isEmpty()) {
98	        lo = *std::min_element(scores_.constBegin(), scores_.constEnd());
99	        hi = *std::max_element(scores_.constBegin(), scores_.constEnd());
100	        const double span = hi - lo;
101	        if (span < 1e-6) {
102	            lo -= 5.0;
103	            hi += 5.0;
104	        } else {
105	            const double pad = span * 0.1;
106	            lo -= pad;
107	            hi += pad;
108	        }
109	    }
110	
111	    // --- 网格 + Y 轴刻度 ---
112	    painter->setPen(QPen(QColor(0xE0, 0xE0, 0xE0), 1, Qt::SolidLine));
113	    QFont small = painter->font();
114	    small.setPointSizeF(std::max(7.0, small.pointSizeF() - 1.0));
115	    painter->setFont(small);
116	
117	    for (int i = 0; i <= kGridLines; ++i) {
118	        const double ratio = static_cast<double>(i) / kGridLines;
119	        const int y = plot.bottom() - static_cast<int>(ratio * plot.height());
120	
121	        painter->setPen(QPen(QColor(0xE0, 0xE0, 0xE0), 1, Qt::SolidLine));
122	        painter->drawLine(plot.left(), y, plot.right(), y);
123	
124	        const double value = lo + ratio * (hi - lo);
125	        painter->setPen(QColor(0x88, 0x88, 0x88));
126	        painter->drawText(QRect(area.left(), y - 8, kMarginLeft - 6, 16),
127	                          Qt::AlignRight | Qt::AlignVCenter,
128	                          QString::number(value, 'f', 0));
129	    }
130	
131	    // --- 数据为空时的提示 ---
132	    if (scores_.isEmpty()) {
133	        painter->setPen(QColor(0x99, 0x99, 0x99));
134	        painter->drawText(plot, Qt::AlignCenter, QStringLiteral("暂无历史数据"));
135	        painter->restore();
136	        return;
137	    }
138	
139	    // --- 折线 ---
140	    // 单点时画一个点，避免除零
141	    const int n = scores_.size();
142	    QPainterPath path;
143	    for (int i = 0; i < n; ++i) {
144	        const double x_ratio =
145	            (n == 1) ? 0.5 : static_cast<double>(i) / static_cast<double>(n - 1);
146	        const double y_ratio = (hi - lo) < 1e-9 ? 0.5 : (scores_[i] - lo) / (hi - lo);
147	
148	        const double x = plot.left() + x_ratio * plot.width();
149	        const double y = plot.bottom() - y_ratio * plot.height();
150	
151	        if (i == 0) {
152	            path.moveTo(x, y);
153	        } else {
154	            path.lineTo(x, y);
155	        }
156	    }
157	
158	    painter->setPen(QPen(line_color_, 2, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin));
159	    painter->setBrush(Qt::NoBrush);
160	    painter->drawPath(path);
161	
162	    // 数据点少于 30 个时补圆点，便于看清具体采样
163	    if (n <= 30) {
164	        painter->setBrush(line_color_);
165	        painter->setPen(Qt::NoPen);
166	        for (int i = 0; i < n; ++i) {
167	            const double x_ratio =
168	                (n == 1) ? 0.5 : static_cast<double>(i) / static_cast<double>(n - 1);
169	            const double y_ratio = (hi - lo) < 1e-9 ? 0.5 : (scores_[i] - lo) / (hi - lo);
170	            const double x = plot.left() + x_ratio * plot.width();
171	            const double y = plot.bottom() - y_ratio * plot.height();
172	            painter->drawEllipse(QPointF(x, y), 2.5, 2.5);
173	        }
174	    }
175	
176	    // --- X 轴首尾时间标签 ---
177	    if (!labels_.isEmpty()) {
